(* [comment removed for export] *)
Definition fbp_TB_state (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (fb n spa ff : Z) (FB : fbv) (t1 t2 t3 t4 t5 t6 : word) (m : mem) : machine_state :=
  MS (mkR (Z_to_bv 64 AFBP_RET_FS) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1 t2
          sp (Z_to_bv 64 spa)
          (Z_to_bv 64 (fb_out FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 u64max) (Z_to_bv 64 (fb_cap FB - fb_size FB))
          (Z_to_bv 64 (fb_size FB + fb_begin FB)) (Z_to_bv 64 ff) (Z_to_bv 64 (fb + 8))
          (Z_to_bv 64 ff) (Z_to_bv 64 n) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880)) (Z_to_bv 64 2147450880)
          (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 (Z.shiftr fb 3 + 2147450880))
          (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3 t4 t5 t6)
     F (Z_to_bv 64 AFBP_TB) fc None m (seg_rom asegs).

(* [comment removed for export] *)
Lemma fbp_B0 : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t1' t2' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp : Z) (FB : fbv)
    (Q : mem -> Prop) (m0 mx : mem) (gap : list cell) (tj0 tj1 tj2 hjunk sh8 : list byte),
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk asegs mx lo spa ->
  rw_cells asegs mx spa (fbp_tmp2 tj0 tj1 tj2 fb ff) ->
  rw_cells asegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells asegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 56 hjunk; C8 (Z_to_bv 64 fp)] ->
