Definition fb_block_cells (FB : fbv) (pre ds junk : list byte) : list cell :=
  [CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length ds) ds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk].

Definition fbp_WB (fb spa ff fp : Z) (FB : fbv) : list (Z * Z) :=
  (fb_begin FB, fb_begin FB + fb_size FB) :: (spa - AINTRIN_STACK, spa) :: fbp_WA fb ff fp.
