  fresh_frame H LF 0 ff fp -> as_RFS H ((0, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi -> mem_inv asegs mx -> as_RFS H LF m0 ->
  (* [comment removed for export] *)
  rw_cells asegs mx (fb_begin FB) (fb_block_cells FB pre ds junk) -> zlength ds = fb_size FB ->
  addressable mx (fb_begin FB) (fb_cap FB) -> shvis mx (fb_begin FB) (fb_end FB) -> aapp (fb_begin FB) (fb_cap FB) -> fsobj H LF (fb_begin FB) (fb_cap FB) ->
